content.query:
let window = customEvents
| where timestamp {TimeRange}
| extend outcome = tostring(customDimensions.outcome), user = tostring(customDimensions.user_id);
let ops = window | where isnotempty(outcome);
let total = toscalar(count_of_ops = ops | count);
union
(ops | summarize Value = round(100.0 * countif(outcome == 'success') / count(), 2) | extend Metric = 'Success rate %'),
(window | summarize Value = todouble(dcount(user)) | extend Metric = 'Distinct users'),
(ops | summarize Value = todouble(count()) | extend Metric = 'Total operations'),
(window | where name == 'OperationFailed' | summarize Value = todouble(count()) | extend Metric = 'Failures'),
(window | where name == 'WorkbookUploaded' | summarize Value = todouble(count()) | extend Metric = 'Workbooks uploaded'),
(window | where name == 'ChartGenerated' | summarize Value = todouble(count()) | extend Metric = 'Charts generated')
| project Metric, Value
